import React from 'react';

import Printer from '@pohodnik/icons/svg/Devices/Printer';

import OneArticleBody from '@apps/Articles/components/OneArticleBody';
import PageHeader from '@components/PageHeader';
import PageLoader from '@components/PageLoader';
import PohAlert, { AlertVariant } from '@ui-kit/Alert';
import Breadcrumb from '@ui-kit/Breadcrumb';
import PohButton, { ButtonVariant } from '@ui-kit/Button';
import PohContainer from '@ui-kit/layout/Container';

import { getHikingDataAsync } from '../@services/hiking.service';
import { getHikingArticlesWithText } from '../@services/hikingArticles.service';
import { IHikingData } from '../@types/hiking.types';
import { IHikingArticleWithText } from '../@types/hikingArticles.types';

interface IHikingArticlesPrintPageProps {
  id_hiking: number;
}

const HikingArticlesPrintPage: React.FC<IHikingArticlesPrintPageProps> = ({ id_hiking }) => {
  const [hikingData, setHikingData] = React.useState<IHikingData | null>(null);
  const [data, setData] = React.useState<IHikingArticleWithText[]>([]);
  const [isLoading, setIsLoading] = React.useState(true);
  const [err, setIsErr] = React.useState<Error>();

  React.useEffect(() => {
    const start = async () => {
      try {
        setIsLoading(true);
        const hd = await getHikingDataAsync(id_hiking);
        setHikingData(hd);

        const dt = await getHikingArticlesWithText(id_hiking);
        setData(dt);
      } catch (error) {
        setIsErr(err as Error);
        console.error(error);
      } finally {
        setIsLoading(false);
      }
    };

    start();
  }, [id_hiking]);

  if (isLoading) {
    return <PageLoader />;
  }

  if (err) {
    return <PohAlert variant={AlertVariant.Danger}>{err.message}</PohAlert>;
  }

  if (!hikingData) {
    return null;
  }

  return (
    <PohContainer>
      <Breadcrumb
        className="d-print-none"
        data={[
          { href: '/hiking', text: 'Походы' },
          { href: `/hiking/${id_hiking}`, text: hikingData.name ?? '' },
          {
            href: `/hiking/${id_hiking}/articles`,
            text: 'Статьи',
            active: true,
          },
        ]}
      />
      <PageHeader title={`Статьи похода «${hikingData.name}»`} className="d-print-none">
        <PohButton onClick={() => window.print()} variant={ButtonVariant.Light} icon>
          <Printer />
        </PohButton>
      </PageHeader>
      <div>
        {data.map((hikingArticle) => {
          return (
            <article
              key={hikingArticle.id}
              className="mb-3 pb-3 border-bottom"
              style={{ breakAfter: 'page' }}
            >
              <header>
                <h3 id={`article-${hikingArticle.id}`}>{hikingArticle.article.name}</h3>
              </header>
              <OneArticleBody text={hikingArticle.article.text} />
            </article>
          );
        })}
      </div>
    </PohContainer>
  );
};

export default HikingArticlesPrintPage;
